package co.serviasigna.domain;

import jakarta.persistence.*;

/**
 * Vehículo con su capacidad en unidades de carga (tabla VEHICULO, RF-M2-02, RN-04).
 * <p>
 * EN: Vehicle with its capacity in load units (VEHICULO table, RF-M2-02, RN-04).
 */
@Entity
@Table(name = "VEHICULO")
public class Vehicle {
    /** El identificador que genera Oracle. EN: The identifier generated by Oracle. */
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    /** La placa. EN: The license plate. */
    @Column(name = "PLACA", nullable = false, length = 10) private String plate;
    /** El tipo de vehículo. EN: The vehicle type. */
    @Column(name = "TIPO", nullable = false, length = 12) private VehicleType type;
    /** La capacidad en unidades de carga. EN: The capacity in load units. */
    @Column(name = "CAPACIDAD_UNIDADES", nullable = false) private int capacityUnits;
    /** El id del domiciliario. EN: The courier id. */
    @Column(name = "DOMICILIARIO_ID") private Long courierId;
    /** Si el vehículo está activo. EN: Whether the vehicle is active. */
    @Column(name = "ACTIVO", nullable = false) private boolean active = true;

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected Vehicle() {}

    /**
     * Crea un vehículo activo.
     * <p>
     * EN: Creates an active vehicle.
     *
     * @param plate placa / license plate
     * @param type tipo de vehículo / vehicle type
     * @param capacityUnits capacidad en unidades de carga / capacity in load units
     * @param courierId id del domiciliario, puede ser null / courier id, may be null
     */
    public Vehicle(String plate, VehicleType type, int capacityUnits, Long courierId) {
        this.plate = plate; this.type = type; this.capacityUnits = capacityUnits; this.courierId = courierId;
    }

    /**
     * Cambia la placa, el tipo y la capacidad.
     * <p>
     * EN: Changes the plate, the type and the capacity.
     *
     * @param plate nueva placa / new plate
     * @param type nuevo tipo / new type
     * @param capacity nueva capacidad en unidades / new capacity in units
     */
    public void update(String plate, VehicleType type, int capacity) { this.plate = plate; this.type = type; this.capacityUnits = capacity; }

    /**
     * Desactiva el vehículo.
     * <p>
     * EN: Deactivates the vehicle.
     */
    public void deactivate() { active = false; }

    /**
     * Devuelve el identificador que genera Oracle.
     * <p>
     * EN: Returns the identifier generated by Oracle.
     *
     * @return el identificador que genera Oracle / the identifier generated by Oracle
     */
    public Long getId() { return id; }

    /**
     * Devuelve la placa.
     * <p>
     * EN: Returns the license plate.
     *
     * @return la placa / the license plate
     */
    public String getPlate() { return plate; }

    /**
     * Devuelve el tipo de vehículo.
     * <p>
     * EN: Returns the vehicle type.
     *
     * @return el tipo de vehículo / the vehicle type
     */
    public VehicleType getType() { return type; }

    /**
     * Devuelve la capacidad en unidades de carga.
     * <p>
     * EN: Returns the capacity in load units.
     *
     * @return la capacidad en unidades de carga / the capacity in load units
     */
    public int getCapacityUnits() { return capacityUnits; }

    /**
     * Devuelve el id del domiciliario.
     * <p>
     * EN: Returns the courier id.
     *
     * @return el id del domiciliario / the courier id
     */
    public Long getCourierId() { return courierId; }

    /**
     * Indica si el vehículo está activo.
     * <p>
     * EN: Tells whether the vehicle is active.
     *
     * @return true si se cumple / true if it applies
     */
    public boolean isActive() { return active; }
}
